<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$sid=(int)$_POST['skill_id'];$type=$_POST['skill_type'];$level=$_POST['proficiency_level'];$years=max(0,(float)$_POST['years_experience']);$desc=trim($_POST['description']??'');try{$s=$pdo->prepare("INSERT INTO UserSkills(user_id,skill_id,skill_type,proficiency_level,years_experience,description) VALUES(?,?,?,?,?,?)");$s->execute([$uid,$sid,$type,$level,$years,$desc]);flash('success','Skill added successfully.');redirect('my-skills.php');}catch(PDOException $e){flash('error','You already have that skill in this category.');}}
$skills=$pdo->query("SELECT s.*,c.category_name FROM Skills s JOIN SkillCategories c ON c.category_id=s.category_id ORDER BY c.category_name,s.skill_name")->fetchAll();$title='Add skill';include 'includes/header.php';
?>
<div class="auth-wrap"><form method="post" class="auth-card form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="eyebrow">EXPAND YOUR PROFILE</div><h1>Add a skill.</h1><label>Skill<select name="skill_id" required><?php foreach($skills as $s):?><option value="<?=$s['skill_id']?>"><?=e($s['category_name'].' · '.$s['skill_name'])?></option><?php endforeach;?></select></label><label>I want to <select name="skill_type"><option value="teach">Teach this</option><option value="learn">Learn this</option></select></label><label>Proficiency<select name="proficiency_level"><?php foreach(['Beginner','Intermediate','Advanced','Expert'] as $x):?><option><?=$x?></option><?php endforeach;?></select></label><label>Years of experience<input type="number" step="0.5" min="0" name="years_experience" value="0"></label><label>Short description<textarea name="description" placeholder="What can you offer or what do you want to learn?"></textarea></label><button class="btn">Add skill →</button></form></div>
<?php include 'includes/footer.php'; ?>
